def compact_ordered_events(seq:list[int],keys:list[str],values:list[int])->list[int]|None:
    if len(seq)!=len(keys) or len(seq)!=len(values):return None
    last={}
    for i,(number,key) in enumerate(zip(seq,keys)):
        if (i and number<=seq[i-1]) or key=='':return None
        last[key]=i
    return [value for i,value in enumerate(values) if last[keys[i]]==i]
